// PATCH: auth-readiness-guidance sends auth failures through local setup
// readiness first, with live sandbox reachability explicitly optional.
func cliAuthReadinessGuidance() string {
	return "Run local setup readiness first: straddle-pp-cli setup check --json" +
		"\n      Save a token with: straddle-pp-cli auth set-token --stdin" +
		"\n      Or have your shell or secret manager inject STRADDLE_TOKEN." +
		"\n      Optional live sandbox reachability: after setting an explicit sandbox base URL and credentials, run straddle-pp-cli doctor --json."
}

func newAuthStatusCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "status",
		Short:   "Show authentication status",
		Example: "  straddle-pp-cli auth status",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			w := cmd.OutOrStdout()
			header := cfg.AuthHeader()
			authed := header != ""
			// JSON envelope: {authenticated, source, config}. When not
			// authenticated, write the envelope first then return authErr
			// so exit code carries the auth-failure signal.
			if flags.asJSON {
				out := map[string]any{
					"authenticated": authed,
					"source":        cfg.AuthSource,
					"config":        cfg.Path,
				}
				if !authed {
					out["auth_hint"] = cliAuthReadinessGuidance()
				}
				if printErr := printJSONFiltered(w, out, flags); printErr != nil {
					return printErr
				}
				if !authed {
					return authErr(fmt.Errorf("no credentials configured"))
				}
				return nil
			}
			if !authed {
				fmt.Fprintln(w, red("Not authenticated"))
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Start with local setup readiness:")
				fmt.Fprintln(w, "  straddle-pp-cli setup check --json")
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Then configure credentials safely:")
				// PATCH: Prefer stdin token setup in unauthenticated guidance so tokens do not pass through argv.
				fmt.Fprintln(w, "  read -r -s STRADDLE_TOKEN_INPUT; straddle-pp-cli auth set-token --stdin <<<\"$STRADDLE_TOKEN_INPUT\"; unset STRADDLE_TOKEN_INPUT")
				fmt.Fprintln(w, "  Or have your shell or secret manager inject STRADDLE_TOKEN.")
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Optional live sandbox reachability:")
				fmt.Fprintln(w, "  After setting an explicit sandbox base URL and credentials, run straddle-pp-cli doctor --json.")
				return authErr(fmt.Errorf("no credentials configured"))
			}

			fmt.Fprintln(w, green("Authenticated"))
			fmt.Fprintf(w, "  Source: %s\n", cfg.AuthSource)
			fmt.Fprintf(w, "  Config: %s\n", cfg.Path)
			return nil
		},
	}
}

func newAuthSetTokenCmd(flags *rootFlags) *cobra.Command {
	// PATCH: Add stdin token setup while keeping legacy positional token compatibility.
	var fromStdin bool
	cmd := &cobra.Command{
		Use:   "set-token --stdin",
		Short: "Save an API token to the config file",
		Long: "Save an API token to the config file.\n\n" +
			"Pass the token on stdin with --stdin so it does not appear in shell history or process lists.",
		Example: "  read -r -s STRADDLE_TOKEN_INPUT\n" +
			"  straddle-pp-cli auth set-token --stdin <<<\"$STRADDLE_TOKEN_INPUT\"\n" +
			"  unset STRADDLE_TOKEN_INPUT",
		Args: func(cmd *cobra.Command, args []string) error {
			if fromStdin && len(args) > 0 {
				return fmt.Errorf("do not provide both --stdin and a token argument")
			}
			if fromStdin {
				return nil
			}
			if len(args) != 1 {
				return fmt.Errorf("token required: use --stdin for safe input")
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}
			token := ""
			if fromStdin {
				// PATCH: Read token from stdin so scripts can avoid exposing credentials through argv.
				data, err := io.ReadAll(cmd.InOrStdin())
				if err != nil {
					return configErr(fmt.Errorf("reading token from stdin: %w", err))
				}
				token = strings.TrimSpace(string(data))
				if token == "" {
					return configErr(fmt.Errorf("token read from stdin is empty"))
				}
			} else {
				token = strings.TrimSpace(args[0])
				if token == "" {
					return configErr(fmt.Errorf("token is empty"))
				}
			}

			// Clear any legacy auth_header so AuthHeader() falls through to
			// the newly-saved credential. Without this, a pre-existing
			// auth_header value (common after regenerate) shadows the saved
			// token and set-token silently has no effect. Silent clear (no
			// log line): a masked-tail variant could leak token bytes through
			// scripted dogfood that captures stderr.
			cfg.AuthHeaderVal = ""
			cfg.StraddleToken = ""
			if err := cfg.SaveTokens("", "", token, "", cfg.TokenExpiry); err != nil {
				return configErr(fmt.Errorf("saving token: %w", err))
			}

			// JSON envelope: {saved, config_path}.
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"saved":       true,
					"config_path": cfg.Path,
				}, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Token saved to %s\n", cfg.Path)
			return nil
		},
	}
	cmd.Flags().BoolVar(&fromStdin, "stdin", false, "Read the token from stdin")
	return cmd
}

func newAuthLogoutCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "logout",
		Short:   "Clear stored credentials",
		Example: "  straddle-pp-cli auth logout",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			if err := cfg.ClearTokens(); err != nil {
				return configErr(fmt.Errorf("clearing tokens: %w", err))
			}

			// Identify which (if any) auth env var is still exported so the
			// JSON envelope and the human prose can both surface it.
			envStillSet := ""
			if envStillSet == "" && os.Getenv("STRADDLE_TOKEN") != "" {
				envStillSet = "STRADDLE_TOKEN"
			}

			// JSON envelope: {cleared: true, note?: "<env_var> env var is still set"}.
			if flags.asJSON {
				out := map[string]any{"cleared": true}
				if envStillSet != "" {
					out["note"] = envStillSet + " env var is still set"
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}

			if envStillSet != "" {
				fmt.Fprintf(cmd.OutOrStdout(), "Config cleared. Note: %s env var is still set.\n", envStillSet)
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), "Logged out. Credentials cleared.")
			return nil
		},
	}
}
